package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_HexInteger() {
        Number expected = Integer.valueOf(0x123);
        assertEquals(expected, NumberUtils.createNumber("0x123"));
    }

    @Test
    public void testCreateNumber_HexNegativeInteger() {
        Number expected = Integer.valueOf(-0x123);
        assertEquals(expected, NumberUtils.createNumber("-0x123"));
    }

    @Test
    public void testCreateNumber_HexUpper() {
        Number expected = Integer.valueOf(0XABC);
        assertEquals(expected, NumberUtils.createNumber("0XABC"));
    }

    @Test
    public void testCreateNumber_HexLong() {
        // More than 8 hex digits after 0x
        Number expected = Long.valueOf(0x123456789L);
        assertEquals(expected, NumberUtils.createNumber("0x123456789"));
    }

    @Test
    public void testCreateNumber_Integer() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
    }

    @Test
    public void testCreateNumber_Long() {
        assertEquals(Long.valueOf(12345678901L), NumberUtils.createNumber("12345678901"));
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigNum = "123456789012345678901234567890";
        assertEquals(new BigInteger(bigNum), NumberUtils.createNumber(bigNum));
    }

    @Test
    public void testCreateNumber_FloatExplicit() {
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23f"));
    }

    @Test
    public void testCreateNumber_DoubleExplicit() {
        assertEquals(Double.valueOf(1.23d), NumberUtils.createNumber("1.23d"));
    }

    @Test
    public void testCreateNumber_LongExplicit() {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
    }

    @Test
    public void testCreateNumber_BigIntegerExplicit() {
        String bigNum = "123456789012345678901234567890";
        assertEquals(new BigInteger(bigNum), NumberUtils.createNumber(bigNum + "L"));
    }

    @Test
    public void testCreateNumber_DecimalExplicit() {
        assertEquals(new BigDecimal("1.23"), NumberUtils.createNumber("1.23d"));
    }

    @Test
    public void testCreateNumber_FloatToDoubleFallback() {
        // A number too large for float but valid for double
        String largeNum = "1e40f"; 
        // The logic falls through from float to double
        assertEquals(Double.valueOf(1e40), NumberUtils.createNumber(largeNum));
    }

    @Test
    public void testCreateNumber_DoubleToBigDecimalFallback() {
        // A number too large for double but valid for BigDecimal
        String hugeNum = "1e1000d";
        assertEquals(new BigDecimal(hugeNum), NumberUtils.createNumber(hugeNum));
    }

    @Test
    public void testCreateNumber_ScientificNotationNoDec() {
        assertEquals(Double.valueOf(1e3), NumberUtils.createNumber("1e3"));
    }

    @Test
    public void testCreateNumber_ScientificNotationWithDec() {
        assertEquals(Double.valueOf(1.23e3), NumberUtils.createNumber("1.23e3"));
    }

    @Test
    public void testCreateNumber_InvalidScientific() {
        // expPos < decPos case: 'e' comes before '.'
        // Note: The logic 'expPos < decPos' triggers exception
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1e.2"));
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("123z"));
    }

    @Test
    public void testCreateNumber_InvalidLongSuffix() {
        // Non-numeric part for Long suffix
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1.23L"));
    }

    @Test
    public void testCreateNumber_AllZerosCase() {
        // Tests the 'allZeros' logic to ensure it doesn't fall back incorrectly
        assertEquals(0.0, NumberUtils.createNumber("0.0").doubleValue(), 0.0001);
        assertEquals(0.0, NumberUtils.createNumber("0e0").doubleValue(), 0.0001);
    }

    @Test
    public void testCreateNumber_ExpTooLarge() {
        // Testing the expPos > str.length() branch
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1e"));
    }

    @Test
    public void testCreateNumber_NegativeHex() {
        assertEquals(Integer.valueOf(-0x1), NumberUtils.createNumber("-0x1"));
    }

    @Test
    public void testCreateNumber_FloatPrecisionLoss() {
        // A number that causes float to be 0.0 but isn't all zeros (to trigger fallback)
        // 1e-50 is very small for float
        String tiny = "1e-50f";
        // Should fall through to Double or BigDecimal
        Number result = NumberUtils.createNumber(tiny);
        assertTrue(result instanceof Double || result instanceof BigDecimal);
    }

    // Helper to handle JUnit 4 lack of assertThrows in older versions if needed
    private void assertThrows(Class<? extends Throwable> expectedType, Runnable runnable) {
        try {
            runnable.run();
            fail("Expected exception " + expectedType.getName() + " but none was thrown.");
        } catch (Throwable t) {
            if (!expectedType.isInstance(t)) {
                fail("Expected exception " + expectedType.getName() + " but caught " + t.getClass().getName());
            }
        }
    }
}
